type dispatcherEventSettingsChanged struct {
	s   *Server
	ctx context.Context
}

func (d dispatcherEventSettingsChanged) Dispatch(e dpapp.EventSettingsChanged) error {
	return d.DispatchCtx(d.ctx, e)
}

func (d dispatcherEventSettingsChanged) DispatchCtx(
	ctx context.Context, e dpapp.EventSettingsChanged,
) error {
	if e.Tab == "" {
		return errors.New("EventSettingsChanged.Tab must not be empty")
	}
	j, err := json.Marshal(e)
	if err != nil {
		return fmt.Errorf("marshaling EventSettingsChanged JSON: %w", err)
	}
	subj := "settings.changed." + subject.Encode(string(e.Tab))
	err = d.s.messageBroker.Publish(ctx, d.s.messageBrokerMetrics, subj, j)
	if err != nil {
		return fmt.Errorf("publishing subject %q: %w", subj, err)
	}
	return nil
}
